import { action, addLimitOption, parseIntArg, parseNonEmpty, pruneUndefined, renderJson, renderRaw, } from "../shared.js";
/** All three XZuFi entity resources share the same cursor-list + xzufi-download shape. */
function registerEntity(program, deps, name, description, pick, 
/** Whether the listing supports full-text search (`fts_query`). */
fullText) {
    const cmd = program.command(name).description(description);
    const list = addLimitOption(cmd
        .command("list")
        .description(`List ${name} (cursor paginated)`)
        .option("--cursor <n>", "pagination cursor (>= 0)", parseIntArg));
    if (fullText)
        list.option("--fts-query <q>", "full-text search query", parseNonEmpty);
    list
        .action(action(deps, async ({ client, global, opts }) => {
        const params = pruneUndefined({
            fts_query: opts["ftsQuery"],
            cursor: opts["cursor"],
            limit: opts["limit"],
        });
        renderJson(deps, global, await pick(client).list(params));
    }));
    cmd
        .command("xzufi")
        .argument("<redaktionId>", "Redaktion id", parseNonEmpty)
        .argument("<id>", "entity id", parseNonEmpty)
        .description(`Download the XZuFi XML for a ${name} entity`)
        .action(action(deps, async ({ client, global }, [redaktionId, id]) => {
        await renderRaw(deps, global, await pick(client).downloadXzufi(redaktionId, id));
    }));
}
export function registerXzufiEntityCommands(program, deps) {
    registerEntity(program, deps, "organizational-units", "Organisationseinheiten (XZuFi)", (c) => c.organizationalUnits, true);
    registerEntity(program, deps, "specializations", "Spezialisierungen (XZuFi)", (c) => c.specializations, false);
    registerEntity(program, deps, "online-services", "Onlinedienste (XZuFi)", (c) => c.onlineServices, true);
}
